## Comparison to measure created by NLSY97 Research team

A$TNMI<-rowSums(data.frame(A$I92,A$I93,A$I94,A$I95,A$I96,A$I97,A$I98,A$I99,
                           A$I00,A$I01,A$I02,A$I03,A$I04,A$I05,A$I06,A$I07,A$I08,A$I09,
                           A$I10,A$I11,A$I12,A$I13,A$I14,A$I15,A$I16,A$I17), na.rm = T)

table(A$TNMI, useNA="always") # This measure ends at the conclusion of 2017
table(A$E8043500, useNA="always") # This measure goes till approximately the ninth month 2018 
table(A$TNMI,A$E8043500,dnn = c("TNMI","E8043500"), useNA="always") # Cross tabs TNMI on the vertical plane, E8043500 on the horizontal plane
corr.test(A$TNMI,A$E8043500, use = "complete",method="spearman")#Correlation between the measures is .95 with the final year of data 
#contributing to the difference between the measures.


