## Latent Growth Model General Health (In->Health) ####
names(B)

FLGMGH<-'
# Latent Factors
I_IN=~1*I96+1*I97+1*I98+1*I99+1*I00+1*I01+1*I02+1*I03+1*I04+1*I05+1*I06+1*I07+1*I08+1*I09+1*I10+1*I11+1*I12+1*I13+1*I14+1*I15+1*I16
S_IN=~0*I96+1*I97+2*I98+3*I99+4*I00+5*I01+6*I02+7*I03+8*I04+9*I05+10*I06+11*I07+12*I08+13*I09+14*I10+15*I11+16*I12+17*I13+18*I14+19*I15+20*I16
I_RGH=~1*RGH97+1*RGH98+1*RGH99+1*RGH00+1*RGH01+1*RGH02+1*RGH03+1*RGH04+1*RGH05+1*RGH06+1*RGH07+1*RGH08+1*RGH09+1*RGH10+1*RGH11+1*RGH13+1*RGH15+1*RGH17
S_RGH=~0*RGH97+1*RGH98+2*RGH99+3*RGH00+4*RGH01+5*RGH02+6*RGH03+7*RGH04+8*RGH05+9*RGH06+10*RGH07+11*RGH08+12*RGH09+13*RGH10+14*RGH11+16*RGH13+18*RGH15+20*RGH17

# Paths

I_IN~MI92_95+Hispanic+White+Black+AIndian+Asian+Female+A92+Sample+HDU
S_IN~MI92_95+Hispanic+White+Black+AIndian+Asian+Female+A92+Sample+HDU
I_RGH~I_IN+S_IN+MI92_95+Hispanic+White+Black+AIndian+Asian+Female+A92+Sample+HDU
S_RGH~I_IN+S_IN+MI92_95+Hispanic+White+Black+AIndian+Asian+Female+A92+Sample+HDU

# Covariances
I_IN~~S_IN
I_RGH~~S_RGH
'

M_LGMGH<-sem(FLGMGH,  std.lv = FALSE, std.ov = FALSE, fixed.x = F, data=E, estimator = "ML", missing = "ML")

sink("Results/Main Model_LGM Model General Health Number of Months In Prison (In-Health) (FIML).txt")
print(summary(M_LGMGH, fit.measures= TRUE, standardized = TRUE, ci = TRUE, rsquare = T))
print(partable(M_LGMGH))
print(inspect(M_LGMGH))
print(resid(M_LGMGH, type = "cor"))
sink()

