names(E$AIndian)
table(E$AIndian)

J<-(E[, c("R0000100","A92","TT92","TT93","TT94","TT95",
          "TT96","TT97","TT98","TT99","TT00","TT01","TT02","TT03","TT04","TT05","TT06","TT07","TT08","TT09",
          "TT10","TT11","TT12","TT13","TT14","TT15","TT16","TT17",
          "RGH97","RGH98","RGH99","RGH00","RGH01","RGH02","RGH03","RGH04","RGH05","RGH06",
          "RGH07","RGH08","RGH09","RGH10","RGH11","RGH13","RGH15","RGH17",
          "DEP00","DEP02","DEP04","DEP06","DEP08","DEP10",
          "DEP15","DEP17","Hispanic","White","Black","AIndian","Asian",
          "Other","Female","Sample","HDU")])

table(J$Asian)
K<-mice(J, m=5, maxit = 50, method = c("pmm","pmm",
                                       "pmm","pmm","pmm","pmm",
                                       "pmm","pmm","pmm","pmm","pmm",
                                       "pmm","pmm","pmm","pmm","pmm",
                                       "pmm","pmm","pmm","pmm","pmm",
                                       "pmm","pmm","pmm","pmm","pmm",
                                       "pmm","pmm","pmm","pmm","pmm",
                                       "pmm","pmm","pmm","pmm","pmm",
                                       "pmm","pmm","pmm","pmm","pmm",
                                       "pmm","pmm","pmm","pmm","pmm",
                                       "pmm","pmm","pmm","pmm","pmm",
                                       "pmm","pmm","pmm",
                                       "norm","norm","norm","norm","norm",
                                       "norm","norm","norm","norm"))

L<-complete(K)

### Creating Transition periods before Analytical timeframe ####
L$TT92_95<-rowSums(data.frame(L$TT92,L$TT93,L$TT94,L$TT95), na.rm = T)
table(L$TT92_95)

L$TT92_96<-rowSums(data.frame(L$TT92,L$TT93,L$TT94,L$TT95,L$TT96), na.rm = T)
table(L$TT92_96)

L$TT92_97<-rowSums(data.frame(L$TT92,L$TT93,L$TT94,L$TT95,L$TT96,L$TT97), na.rm = T)
table(L$TT92_97)

L$TT92_98<-rowSums(data.frame(L$TT92,L$TT93,L$TT94,L$TT95,L$TT96,L$TT97,L$TT98), na.rm = T)
table(L$TT92_98)

L$TT92_99<-rowSums(data.frame(L$TT92,L$TT93,L$TT94,L$TT95,L$TT96,L$TT97,L$TT98,L$TT99), na.rm = T)
table(L$TT92_99)

L$TT92_00<-rowSums(data.frame(L$TT92,L$TT93,L$TT94,L$TT95,L$TT96,L$TT97,L$TT98,L$TT99,L$TT00), na.rm = T)
table(L$TT92_00)





fwrite(L,"Imputed Transition Data.csv", buffMB = 1024L, append = T, sep = ",", quote = F, compress = "none")  


